  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  'c30141a1-f37e-532e-b49e-31b875e6eff2'::uuid, null, 'Creative Energy Collector''s Edition', 'commander', 'Creative Energy Collector''s Edition is an official Commander precon from M3C, released 2024-06-14.', 'public', true, true,
