  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  '9e8178b5-644b-5f03-8836-b11aea0d1f61'::uuid, null, 'Graveyard Overdrive Collector''s Edition', 'commander', 'Graveyard Overdrive Collector''s Edition is an official Commander precon from M3C, released 2024-06-14.', 'public', true, true,
