  color_identity, oracle_text, quantity, board
)
select v.deck_id, v.scryfall_id, v.card_name, v.image_uri, v.mana_cost, v.type_line, v.colors,
  v.color_identity, v.oracle_text, v.quantity, v.board
from (values
  ('ab4c2307-eb48-54c3-9890-89b6ae9e7c18'::uuid, '2f5b4544-70d9-45ee-84a3-fa6253a53a82', 'Academy Manufactor', 'https://cards.scryfall.io/normal/front/2/f/2f5b4544-70d9-45ee-84a3-fa6253a53a82.jpg', '{3}', 'Artifact Creature — Assembly-Worker', '{}'::text[], '{}'::text[], 'If you would create a Clue, Food, or Treasure token, instead create one of each.', 1, 'main'),
