) values (
  '2e919386-cac8-597d-8dc1-e70a34ce8842'::uuid, null, 'Eternal Might', 'commander', 'Eternal Might is an official Commander precon from DRC, released 2025-02-14.', 'public', true, true,
  'c0629894-0b72-4abe-9771-03becfdb241c', 'Temmet, Naktamun''s Will', 'Legendary Creature — Zombie Wizard', '{2}{W}{U}{B}',
  'https://cards.scryfall.io/normal/front/c/0/c0629894-0b72-4abe-9771-03becfdb241c.jpg', 'https://cards.scryfall.io/art_crop/front/c/0/c0629894-0b72-4abe-9771-03becfdb241c.jpg', ARRAY['W', 'U', 'B']::text[], ARRAY['W', 'U', 'B']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
