insert into public.decks (
  id, owner_id, name, format, notes, visibility, allow_forks, is_precon,
  commander_scryfall_id, commander_name, commander_type_line, commander_mana_cost,
  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  'c3c01723-aaf2-5e51-92e8-5c4144b49a92'::uuid, null, 'Everyone''s Invited!', 'commander', 'Everyone''s Invited! is an official Commander precon from SLD, released 2025-05-12.', 'public', true, true,
  '58e4a55f-b35a-411a-9a05-0cbb0d767920', 'Morophon, the Boundless', 'Legendary Creature — Shapeshifter', '{7}',
  'https://cards.scryfall.io/normal/front/5/8/58e4a55f-b35a-411a-9a05-0cbb0d767920.jpg', 'https://cards.scryfall.io/art_crop/front/5/8/58e4a55f-b35a-411a-9a05-0cbb0d767920.jpg', ARRAY['W', 'U', 'B', 'R', 'G']::text[], ARRAY['W', 'U', 'B', 'R', 'G']::text[]
) on conflict (id) do update set
